// Real three-level native manager/controllers/tools; local temporary A/B, stub LLM.
import assert from 'node:assert/strict';
import {randomUUID} from 'node:crypto';
import {realpath,writeFile} from 'node:fs/promises';
import {join} from 'node:path';
import {host,load,sessions,llm,sourceHandles,user,cleanup} from './native-runtime-rig.mjs';
const signal=()=>new AbortController().signal;
const control=(h,agent,name,args,id)=>h.ctx.tools.execute({agent,calls:[{type:'tool-call',id:llm.ToolCallId(id),name,arguments:JSON.stringify(args)}],signal:signal()});
const settle=async(h,a)=>{await a.whenIdle();await h.ctx.sessionTitle.refresh(a.session);await new Promise(r=>setImmediate(r));};
try {
 const air=await host('tree-air',true),mini=await host('tree-mini',true),A=await realpath(air.workspacePath),B=await realpath(mini.workspacePath);
 await writeFile(join(A,'identity.txt'),'actual native read: AIR A');await writeFile(join(B,'identity.txt'),'actual native read: MINI B');
 await air.sharing.setMapping('verified-host',A,A,A);await mini.sharing.setMapping('verified-host',A,B,B);
 for(const h of [air,mini]){await h.mount((await load('dsh-subagent')).default,{maxDepth:3,maxActiveSubagents:8});await h.mount(await load('dsh-subagent-spawn-in-process'),{providerName:'spawn'});await h.mount(await load('dsh-tool-subagent-control'));}
 const handle=await air.ctx.agents.create({sessionId:sessions.SessionId(randomUUID()),meta:{cwd:A},agentOptions:{provider:'test-native',model:'model'}});sourceHandles.push(handle);const root=handle.agent;
 await (await air.ctx.workspaceRegistry.create(A)).attachSession(root.id);root.followup(user('Root source raw text must remain unchanged'));await settle(air,root);
 const oldChild=sessions.SessionId(randomUUID()),oldGrand=sessions.SessionId(randomUUID());
 air.ctx.tools.register({name:'history_tool',description:'Isolated text result',parameters:{type:'object',properties:{}},output:{schema:{type:'string'},render:(_a,v)=>[{type:'text',text:v}]},execute:async()=>`RAW TOOL ORIGINAL ${root.id} ${oldChild} ${oldGrand}`});
 air.scriptTool(oldChild,'history_tool',{});
 const childPause=air.armModelDelay(oldChild),childRun=await air.ctx.subagents.startActivation({provider:'spawn',childId:oldChild,label:'child',request:{parent:root,prompt:[{type:'text',text:`RAW CHILD ORIGINAL ${root.id} ${oldGrand}`}],maxDepth:3},signal:signal(),delivery:'caller'});await childPause.arrived;
 const child=air.ctx.agents.get(oldChild);air.ctx.permissionPresets.set(child.session,'danger-full-access');child.session.append('sandbox/mode',{mode:'danger-full-access'});child.session.append('approval/policy',{policy:'never'});
 const grandPause=air.armModelDelay(oldGrand),grandRun=await air.ctx.subagents.startActivation({provider:'spawn',childId:oldGrand,label:'grandchild',request:{parent:child,prompt:[{type:'text',text:`RAW GRAND ORIGINAL ${oldChild} ${root.id}`}],maxDepth:3},signal:signal(),delivery:'caller'});await grandPause.arrived;
 const grand=air.ctx.agents.get(oldGrand);air.ctx.permissionPresets.set(grand.session,'danger-full-access');grand.session.append('sandbox/mode',{mode:'danger-full-access'});grand.session.append('approval/policy',{policy:'never'});
 grandPause.release();await grand.whenIdle();await grandRun.dispose();await grandRun.result;
 childPause.release();await child.whenIdle();await childRun.dispose();await childRun.result;
 const observe=async(h,id)=>{const o=await h.ctx.sessionQuery.observeSession(id,{projectionMode:'none'});try{return {header:structuredClone(o.header),events:structuredClone(o.events)};}finally{o[Symbol.dispose]();}};
 const sourceChild=await observe(air,oldChild),sourceGrand=await observe(air,oldGrand);
 assert.ok(sourceChild.events.some(e=>e.type==='sandbox/mode'&&e.data.mode==='danger-full-access'));assert.ok(sourceChild.events.some(e=>e.type==='approval/policy'&&e.data.policy==='never'));
 const shared=await air.sharing.share(root.id,'verified-host');
 let created=0;mini.ctx.on('agent/created',()=>created++,{global:true});const before=mini.calls.length;
 const mirror=await mini.sharing.open('verified-host',shared.sharedId,false);assert.equal(created,0,'cold mirror import creates no agent');assert.equal(mini.calls.length,before);
 const opened=await mini.sharing.open('verified-host',shared.sharedId,true),receiver=mini.ctx.agents.get(opened.sessionId),owner=mini.sharing.autonomyOwner(receiver.id),newChild=owner.agentAliases[oldChild],newGrand=owner.agentAliases[oldGrand];
 assert.equal(created,1,'explicit root continuation creates only its root');assert.equal(mini.calls.length,before);assert.equal(mini.ctx.agents.get(newChild),undefined);assert.equal(mini.ctx.agents.get(newGrand),undefined);
 const importedChild=await observe(mini,newChild),importedGrand=await observe(mini,newGrand);
 assert.equal(importedChild.header.parentSession,receiver.id);assert.equal(importedGrand.header.parentSession,newChild);assert.equal(importedChild.header.createdAt,sourceChild.header.createdAt);assert.equal(importedGrand.header.createdAt,sourceGrand.header.createdAt);
 const visible=events=>events.filter(e=>['user/message','assistant/message','tool/result'].includes(e.type)).map(e=>e.data);
 assert.deepEqual(visible(importedChild.events.slice(0,sourceChild.events.length)),visible(sourceChild.events));assert.deepEqual(visible(importedGrand.events.slice(0,sourceGrand.events.length)),visible(sourceGrand.events));
 const resumedChildPause=mini.armModelDelay(newChild);
 const sent=await control(mini,receiver,'send_message',{agent_id:oldChild,message:'Explicit cold child continuation'},'cold-child');assert.ok(!sent.results[0].result.isError,JSON.stringify(sent));await resumedChildPause.arrived;
 const c=mini.ctx.agents.get(newChild);assert.equal(mini.ctx.sandboxPolicy.resolve({session:c.session}).mode,'read-only');assert.notEqual(mini.ctx.permissionPresets.current(c.session),'danger-full-access');assert.equal(c.session.snapshotEvents().findLast(e=>e.type==='approval/policy').data.policy,'ask');
 const readB=await control(mini,c,'read',{file_path:'identity.txt'},'real-read-B');assert.match(JSON.stringify(readB),/actual native read: MINI B/);assert.doesNotMatch(JSON.stringify(readB),/actual native read: AIR A/);
 const grandResumePause=mini.armModelDelay(newGrand),grandSent=await control(mini,c,'send_message',{agent_id:oldGrand,message:'Explicit grandchild continuation'},'cold-grand');assert.ok(!grandSent.results[0].result.isError,JSON.stringify(grandSent));await grandResumePause.arrived;
 const g=mini.ctx.agents.get(newGrand);assert.equal(mini.ctx.sandboxPolicy.resolve({session:g.session}).mode,'read-only');assert.notEqual(mini.ctx.permissionPresets.current(g.session),'danger-full-access');
 const reply=await control(mini,g,'send_message',{agent_id:oldChild,message:'Grandchild to original child ID'},'grand-up');assert.ok(!reply.results[0].result.isError,JSON.stringify(reply));
 const forbidden=await control(mini,receiver,'send_message',{agent_id:oldGrand,message:'must reject non-adjacent delivery'},'skip-level');assert.equal(forbidden.results[0].result.isError,true);
 const foreign=await mini.ctx.agents.create({sessionId:sessions.SessionId(randomUUID()),meta:{cwd:B},agentOptions:{provider:'test-native',model:'model'}});sourceHandles.push(foreign);
 const unrelated=await control(mini,c,'send_message',{agent_id:foreign.agent.id,message:'must reject unrelated root'},'unrelated-root');assert.equal(unrelated.results[0].result.isError,true);assert.equal(foreign.agent.inbox.nextTurn.length,0);
 const up=await control(mini,c,'send_message',{agent_id:root.id,message:'Child to original root ID'},'child-up');assert.ok(!up.results[0].result.isError,JSON.stringify(up));await settle(mini,receiver);
 mini.ctx.subagents.interrupt(newGrand,{kind:'ancestor',agent:receiver});grandResumePause.release();await mini.ctx.subagents.drainChildren(c,[newGrand]);
 mini.ctx.subagents.interrupt(newChild,{kind:'ancestor',agent:receiver});resumedChildPause.release();await mini.ctx.subagents.drainChildren(receiver,[newChild]);
 await mini.ctx.subagents.waitForChildren(receiver);await new Promise(r=>setImmediate(r));await settle(mini,receiver);
 await mini.sharing.checkpoint(receiver.id);await mini.sharing.handoff(receiver.id);
 const back=await air.sharing.open('verified-host',shared.sharedId,true),backRoot=air.ctx.agents.get(back.sessionId);await air.sharing.checkpoint(backRoot.id);
 const readA=await control(air,backRoot,'read',{file_path:'identity.txt'},'real-read-A');assert.match(JSON.stringify(readA),/actual native read: AIR A/);assert.doesNotMatch(JSON.stringify(readA),/actual native read: MINI B/);
 const backOwner=air.sharing.autonomyOwner(backRoot.id),backChild=backOwner.agentAliases[oldChild];assert.ok(backChild&&backChild!==oldChild&&backChild!==newChild);
 const backLog=await observe(air,backChild);assert.deepEqual(visible(backLog.events.slice(0,sourceChild.events.length)),visible(sourceChild.events));assert.equal(backLog.header.cwd,A);
 const backPause=air.armModelDelay(backChild);
 const backDelivery=await control(air,backRoot,'send_message',{agent_id:newChild,message:'Continue after canonical return using the Mini historical child ID'},'return-cold-child');assert.ok(!backDelivery.results[0].result.isError,JSON.stringify(backDelivery));await backPause.arrived;
 const backChildAgent=air.ctx.agents.get(backChild);assert.equal(air.ctx.sandboxPolicy.resolve({session:backChildAgent.session}).mode,'read-only');assert.notEqual(air.ctx.permissionPresets.current(backChildAgent.session),'danger-full-access');
 air.ctx.subagents.interrupt(backChild,{kind:'ancestor',agent:backRoot});backPause.release();await air.ctx.subagents.drainChildren(backRoot,[backChild]);await new Promise(r=>setImmediate(r));await settle(air,backRoot);
 backRoot.followup(user('Continue after canonical Mini to Air roundtrip'));await settle(air,backRoot);await air.sharing.checkpoint(backRoot.id);
 process.stdout.write(JSON.stringify({threeLevels:true,sourceFullAccessRecorded:true,coldImportZeroExecution:true,childReceiverReadOnly:true,grandchildReceiverReadOnly:true,scopedHistoricalAliases:true,skipLevelDenied:true,unrelatedDenied:true,returnChildReadOnly:true,rawUserToolVerbatim:true,roundTripCheckpoint:true,realReadCwdAtoBtoA:true,stubLLM:true,localTemporaryInstances:true})+'\n');
} finally {await cleanup();}
